#define GL_GLEXT_PROTOTYPES 1
#include <EGL/egl.h>
#include <GL/gl.h>
#include <stdio.h>
#include <stdlib.h>
static char *read_all(const char *p){FILE*f=fopen(p,"rb");long n;char*s;if(!f)return 0;fseek(f,0,SEEK_END);n=ftell(f);fseek(f,0,SEEK_SET);s=calloc((size_t)n+1,1);if(!s||fread(s,1,(size_t)n,f)!=(size_t)n){free(s);s=0;}fclose(f);return s;}
int main(int ac,char**av){if(ac!=2)return 2;EGLDisplay d=eglGetDisplay(EGL_DEFAULT_DISPLAY);EGLint ma,mi,n;if(d==EGL_NO_DISPLAY||!eglInitialize(d,&ma,&mi)||!eglBindAPI(EGL_OPENGL_API))return 1;const EGLint ca[]={EGL_SURFACE_TYPE,EGL_PBUFFER_BIT,EGL_RENDERABLE_TYPE,EGL_OPENGL_BIT,EGL_RED_SIZE,8,EGL_GREEN_SIZE,8,EGL_BLUE_SIZE,8,EGL_ALPHA_SIZE,8,EGL_NONE};EGLConfig cfg;if(!eglChooseConfig(d,ca,&cfg,1,&n)||n==0){fprintf(stderr,"eglChooseConfig returned %d configs\n",n);return 1;}const EGLint pa[]={EGL_WIDTH,16,EGL_HEIGHT,16,EGL_NONE};const EGLint xa[]={EGL_CONTEXT_MAJOR_VERSION,4,EGL_CONTEXT_MINOR_VERSION,3,EGL_CONTEXT_OPENGL_PROFILE_MASK,EGL_CONTEXT_OPENGL_CORE_PROFILE_BIT,EGL_NONE};EGLSurface s=eglCreatePbufferSurface(d,cfg,pa);EGLContext c=eglCreateContext(d,cfg,EGL_NO_CONTEXT,xa);if(s==EGL_NO_SURFACE||c==EGL_NO_CONTEXT||!eglMakeCurrent(d,s,s,c))return 1;char*src=read_all(av[1]);if(!src)return 1;GLuint sh=glCreateShader(GL_FRAGMENT_SHADER);glShaderSource(sh,1,(const GLchar**)&src,0);glCompileShader(sh);GLint ok=0;glGetShaderiv(sh,GL_COMPILE_STATUS,&ok);if(!ok){GLint z;glGetShaderiv(sh,GL_INFO_LOG_LENGTH,&z);char*e=calloc(z+1,1);glGetShaderInfoLog(sh,z,0,e);fputs(e,stderr);free(e);return 1;}GLuint p=glCreateProgram();glAttachShader(p,sh);glLinkProgram(p);glGetProgramiv(p,GL_LINK_STATUS,&ok);if(!ok){GLint z;glGetProgramiv(p,GL_INFO_LOG_LENGTH,&z);char*e=calloc(z+1,1);glGetProgramInfoLog(p,z,0,e);fputs(e,stderr);free(e);return 1;}puts("OK");return 0;}
